// Cyrus limits (owner rule 2026-10-12, "warn, don't block"; docs/cyrus/10-decisions.md D-62): the ONE model of a
// user-chosen number's range. Cyrus never hard-caps a choice a user is allowed to make: a range is a RECOMMENDATION with
// tiers, and only crash-safe bounds (type overflow, negative counts, division by zero) are hard.
//   ok      inside the recommended range (and inside the balanced band, when one is declared)
//   info    inside the recommended range but outside the balanced band (balance note, nothing to confirm)
//   warn    outside the recommended range: amber banner with the likely consequence; applies as set
//   danger  past the warn bound (or DANGER_FACTOR x the recommended max when none is declared): red outline, the
//           editor asks for one confirm; still applies as set
//   invalid outside a HARD (crash-safe) bound: the editor refuses it and a generated loader clamps to it
// Pure + client-safe (the Config Studio, the designers, the planner and the Prompt Coach all read it).

export type LimitTier = "ok" | "info" | "warn" | "danger" | "invalid";
export const TIER_RANK: Record<LimitTier, number> = { ok: 0, info: 1, warn: 2, danger: 3, invalid: 4 };

/** A soft range. Every field is optional; `hard*` may only be set for crash/corruption safety (see policy.ts HARD_KEEP). */
export type SoftRange = {
  recommendedMin?: number;
  recommendedMax?: number;
  /** Past these the tier is "danger" (one confirm). Default: DANGER_FACTOR x recommendedMax above, none below. */
  warnMin?: number;
  warnMax?: number;
  /** Crash-safe bounds only (overflow, negative counts, div by zero). Outside = invalid / clamped by loaders. */
  hardMin?: number;
  hardMax?: number;
  /** An optional balance band inside the recommended range (the Config Studio's `safe`): outside it = info. */
  balancedMin?: number;
  balancedMax?: number;
};

/** How the cost of a value grows, for the plain consequence line ("20 chunks = 1,600 mirrored changes per block"). */
export type Impact = {
  /** linear: factor*v; square: factor*v^2; cube: factor*v^3; inverse: factor/v (e.g. a period in ticks -> runs per second). */
  model: "linear" | "square" | "cube" | "inverse";
  factor?: number;
  /** What the computed number counts ("mirrored changes per block", "runs per second"). */
  unit: string;
  /** The likely consequence ("expect lag on most servers; the TPS safety net can pause it"). */
  note?: string;
};

/** When no warn bound is declared, "danger" starts at this many times the recommended maximum (positive maxima only). */
export const DANGER_FACTOR = 4;

export type LimitVerdict = {
  tier: LimitTier;
  side?: "below" | "above";
  /** The bound that was crossed (recommended / warn / hard / balanced, depending on the tier). */
  bound?: number;
  message: string;
  /** One plain line about the likely consequence (warn / danger only). */
  consequence?: string;
};

const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const trim = (x: number) => String(Math.round(x * 1e4) / 1e4);
export const fmtCount = (n: number) => (Math.abs(n) >= 1000 ? Math.round(n).toLocaleString("en-US") : trim(n));

/** The effective danger bounds of a range (declared, or derived from the recommended max). */
export function dangerBounds(r: SoftRange): { min?: number; max?: number } {
  const max = r.warnMax ?? (r.recommendedMax !== undefined && r.recommendedMax > 0 ? r.recommendedMax * DANGER_FACTOR : undefined);
  return { min: r.warnMin, max };
}

/** factor * f(v) for an impact model (never NaN; inverse of 0 is Infinity). */
export function impactValue(i: Impact, v: number): number {
  const f = i.factor ?? 1;
  switch (i.model) {
    case "linear": return f * v;
    case "square": return f * v * v;
    case "cube": return f * v * v * v;
    case "inverse": return v === 0 ? Infinity : f / v;
  }
}

/** "20 chunks = 1,600 mirrored changes per block; expect lag on most servers; the TPS safety net can pause it". */
export function consequenceLine(v: number, unit: string | undefined, i: Impact | undefined, fallback?: string): string | undefined {
  if (!i) return fallback;
  const n = impactValue(i, v);
  // the "v = n unit" head only when it says something new (not for an empty unit or a plain 1x linear model)
  const echo = !i.unit || (i.model === "linear" && (i.factor ?? 1) === 1);
  const head = Number.isFinite(n) && !echo ? `${trim(v)}${unit ? ` ${unit}` : ""} = ${fmtCount(n)} ${i.unit}` : "";
  const out = [head, i.note ?? fallback].filter(Boolean).join("; ");
  return out || undefined;
}

export type ClassifyOpts = { label?: string; unit?: string; impact?: Impact; balancedNote?: string; fallbackConsequence?: string };

/** Classify one number against a soft range. */
export function classify(value: number, r: SoftRange, o: ClassifyOpts = {}): LimitVerdict {
  const label = o.label ?? "This value";
  const u = o.unit ? ` ${o.unit}` : "";
  const shown = `${label} ${isNum(value) ? trim(value) : String(value)}${u}`;
  if (!isNum(value)) return { tier: "invalid", message: `${label} needs a finite number` };
  if (r.hardMin !== undefined && value < r.hardMin) return { tier: "invalid", side: "below", bound: r.hardMin, message: `${shown} is below ${trim(r.hardMin)}${u}, the lowest value that works at all` };
  if (r.hardMax !== undefined && value > r.hardMax) return { tier: "invalid", side: "above", bound: r.hardMax, message: `${shown} is above ${trim(r.hardMax)}${u}, the highest value that works at all` };
  const rec = `${r.recommendedMin !== undefined ? trim(r.recommendedMin) : "..."}-${r.recommendedMax !== undefined ? trim(r.recommendedMax) : "..."}${u}`;
  const d = dangerBounds(r);
  const cons = (side: "below" | "above") => consequenceLine(value, o.unit, side === "above" || o.impact?.model === "inverse" ? o.impact : undefined, o.fallbackConsequence ?? genericConsequence(side));
  if (d.max !== undefined && value > d.max) return { tier: "danger", side: "above", bound: d.max, message: `${shown} is far above the recommended ${rec}`, consequence: cons("above") };
  if (d.min !== undefined && value < d.min) return { tier: "danger", side: "below", bound: d.min, message: `${shown} is far below the recommended ${rec}`, consequence: cons("below") };
  if (r.recommendedMax !== undefined && value > r.recommendedMax) return { tier: "warn", side: "above", bound: r.recommendedMax, message: `${shown} is above the recommended ${rec}`, consequence: cons("above") };
  if (r.recommendedMin !== undefined && value < r.recommendedMin) return { tier: "warn", side: "below", bound: r.recommendedMin, message: `${shown} is below the recommended ${rec}`, consequence: cons("below") };
  const note = o.balancedNote ? `: ${o.balancedNote}` : "";
  if (r.balancedMax !== undefined && value > r.balancedMax) return { tier: "info", side: "above", bound: r.balancedMax, message: `${shown} is above the balanced range (${trim(r.balancedMax)}${u} or less)${note}` };
  if (r.balancedMin !== undefined && value < r.balancedMin) return { tier: "info", side: "below", bound: r.balancedMin, message: `${shown} is below the balanced range (${trim(r.balancedMin)}${u} or more)${note}` };
  return { tier: "ok", message: `${shown} is inside the recommended ${rec}` };
}

export function genericConsequence(side: "below" | "above"): string {
  return side === "above"
    ? "the mod does more work or hits harder than it was tuned for: test it on your server first; the TPS safety net can pause heavy features if the server lags"
    : "the mod may behave differently from how it was tuned: test it on your server first";
}

/** Clamp to the HARD bounds only (what a generated loader does). Returns the value and whether it moved. */
export function clampHard(value: number, r: Pick<SoftRange, "hardMin" | "hardMax">): { value: number; clamped: boolean } {
  let y = value;
  if (r.hardMin !== undefined && y < r.hardMin) y = r.hardMin;
  if (r.hardMax !== undefined && y > r.hardMax) y = r.hardMax;
  return { value: y, clamped: y !== value };
}

/** The worst tier of several verdicts. */
export const worstTier = (vs: readonly { tier: LimitTier }[]): LimitTier => vs.reduce<LimitTier>((w, v) => (TIER_RANK[v.tier] > TIER_RANK[w] ? v.tier : w), "ok");

/** Java int / long limits (crash-safe bounds for whole-number settings read into int / long fields). */
export const INT32 = { min: -2147483648, max: 2147483647 } as const;

/** The finite ceiling used for "no real upper bound" (finite, exact in a double, far inside Java long). */
export const SAFE_HARD_MAX = 1e9;

/**
 * Crash-safe bounds for a designer cap whose numbers are a recommendation: never negative when the recommended range
 * is not (negative counts / times / radii), at least 1 when the recommended minimum is 1 or more (zero periods,
 * zero charges, empty stacks), and a finite ceiling. `keep` names caps whose range IS a real boundary (API ceilings,
 * probabilities, stack sizes): those stay exactly as declared.
 */
export function hardCaps<K extends string>(caps: Readonly<Record<K, readonly [number, number]>>, keep: Partial<Record<K, readonly [number, number]>> = {}): Record<K, readonly [number, number]> {
  const out = {} as Record<K, readonly [number, number]>;
  for (const k of Object.keys(caps) as K[]) {
    const [lo] = caps[k];
    out[k] = keep[k] ?? [lo < 0 ? -SAFE_HARD_MAX : lo >= 1 ? 1 : 0, SAFE_HARD_MAX];
  }
  return out;
}

/** A [min, max] range that also carries its crash-safe bounds (designer cap helpers return these). */
export type CapRange = readonly [number, number] & { readonly hard?: readonly [number, number] };
export const withHard = (rec: readonly [number, number], hard: readonly [number, number]): CapRange => Object.assign([rec[0], rec[1]] as [number, number], { hard });
// Config Studio delivery: the value check at the PREFLIGHT of deliverConfig, with the owner's standing rule
// "WARN, DON'T BLOCK" (2026-10-12): a value outside the spec's min/max is a recommended-range warning that rides on
// the result (notes), it never refuses the delivery and the value is written exactly as saved (never clamped).
// What stays a hard refusal is what would corrupt or confuse the file: wrong type/shape, a read-only key, an unknown key.
//
// RECONCILE AT MERGE: branch feature/cyrus-warn-dont-block is changing the validation core (lib/cyrus/config/values.ts).
// When its soft path is on main, this file shrinks to a call of it; until then the strictness is decided HERE, at the
// delivery call site, on top of the unchanged checkValues(..., "strict").
import { coerce, checkValues, type ValueIssue } from "../config/values";
import { paramByKey, type ConfigSpec, type ConfigValue, type ConfigValues } from "../config/spec";

export type SoftCheck = { ok: boolean; values: ConfigValues; errors: ValueIssue[]; warnings: ValueIssue[]; /** keys whose value is outside the spec's limits (their limits are lifted for the write: see relaxLimits) */ outside: string[] };

/** A copy of the spec without min/max on the given keys (the param, its list items, its table columns), so the file writer (lib/cyrus/config/file.ts, which checks "strict" itself) writes the value as saved. */
export function relaxLimits(spec: ConfigSpec, keys: readonly string[]): ConfigSpec {
  if (!keys.length) return spec;
  const lift = <T extends { min?: number; max?: number }>(x: T): T => ({ ...x, min: undefined, max: undefined });
  const set = new Set(keys);
  return { ...spec, params: spec.params.map((p) => (set.has(p.key) ? { ...lift(p), ...(p.item ? { item: lift(p.item) } : {}), ...(p.columns ? { columns: p.columns.map(lift) } : {}) } : p)) };
}

/** Strict shape checks; out-of-range numbers (and list/table cells) become warnings and keep their saved value. */
export function checkConfigValuesSoft(spec: ConfigSpec, values: Record<string, unknown>): SoftCheck {
  const strict = checkValues(spec, values, "strict");
  const errors = strict.errors.filter((e) => e.code !== "outside_limits");
  const limits = strict.errors.filter((e) => e.code === "outside_limits");
  const out: ConfigValues = { ...strict.values };
  const byKey = paramByKey(spec);
  const warnings: ValueIssue[] = [...strict.warnings];
  const outside: string[] = [];
  for (const e of limits) {
    const p = byKey.get(e.key);
    if (!p) { errors.push(e); continue; }
    out[e.key] = coerce(p, values[e.key]) as ConfigValue;
    outside.push(e.key);
    warnings.push({ key: e.key, code: "outside_recommended", message: `${e.message.replace("is outside the allowed", "is outside the recommended")} (sent as you saved it; the server may lag or the mod may clamp it)` });
  }
  return { ok: errors.length === 0, values: out, errors, warnings, outside: [...new Set(outside)] };
}
