/** Warnings for list items / table cells outside a cell's recommended min/max (never an error). */
function cellWarnings(p: ConfigParam, c: Pick<CellSpec, "min" | "max">, label: string, x: unknown): ValueIssue | null {
  if (typeof x !== "number") return null;
  if ((c.min !== undefined && x < c.min) || (c.max !== undefined && x > c.max)) return { key: p.key, code: x < (c.min ?? -Infinity) ? "below_recommended" : "above_recommended", tier: "warn", message: `${p.label}: ${label} ${x} is outside the recommended ${c.min ?? "..."}-${c.max ?? "..."}` };
