export const defaultsOf = (spec: Pick<ConfigSpec, "params">): ConfigValues => Object.fromEntries(spec.params.map((p) => [p.key, structuredClone(p.default)]));

export type ValuesCheck = { ok: boolean; values: ConfigValues; errors: ValueIssue[]; warnings: ValueIssue[]; clamped: string[] };

/**
 * Check a full or partial value set against the spec. Missing keys take the default. Unknown keys are errors
 * (strict) or ignored with a warning (clamp: reading a file the server owner edited). Read-only keys may not change.
 */
export function checkValues(spec: ConfigSpec, values: Record<string, unknown>, mode: ValueMode = "strict", base: ConfigValues = defaultsOf(spec)): ValuesCheck {
  const byKey = paramByKey(spec);
  const errors: ValueIssue[] = [], warnings: ValueIssue[] = [], clamped: string[] = [];
  const out: ConfigValues = { ...base };
  const entries = Object.entries(values ?? {});
  if (entries.length > CONFIG_LIMITS.params) return { ok: false, values: out, errors: [{ key: "", code: "too_many", message: `at most ${CONFIG_LIMITS.params} settings` }], warnings, clamped };
  for (const [k, raw] of entries) {
    const p = byKey.get(k);
    if (!p) { (mode === "strict" ? errors : warnings).push({ key: k, code: "unknown_key", message: `${k} is not a setting of this mod` }); continue; }
    const r = checkValue(p, raw, mode);
    if (!r.ok) { errors.push(r.error); continue; }
    if (p.readOnly && !sameValue(r.value, base[k] ?? p.default)) { errors.push({ key: k, code: "read_only", message: `${p.label} cannot be changed here` }); continue; }
    out[k] = r.value;
    if (r.clamped) clamped.push(k);
    warnings.push(...r.warnings);
  }
  for (const p of spec.params) if (!entries.some(([k]) => k === p.key)) warnings.push(...rangeWarnings(p, out[p.key]));
  return { ok: errors.length === 0, values: out, errors, warnings, clamped };
}

