export const DESIGN_LIMITS = { maxItems: 6, maxSpecBytes: 64 * 1024, maxAbilities: 6, maxNodes: 48, maxDepth: 3, maxConditions: 8, maxActions: 16, maxMarks: 4, maxPassives: 4, maxLore: 6, maxPermissions: 8 } as const;

/**
 * Hard caps on every number (inclusive). The config loader clamps to the SAME caps at runtime, so a hand-edited
 * config.yml can never exceed them. Ticks: 20 = 1 second.
 */
export const CAPS = {
  cooldownTicks: [0, 72000], // up to 1 hour
  chargesMax: [1, 20],
  chargeRegenTicks: [20, 72000],
  targetRange: [1, 32], // blocks the click triggers look for a target / point
  periodTicks: [10, 1200], // held_interval: never faster than twice a second
  minChargeTicks: [5, 200],
  maxChargeTicks: [10, 400],
  damage: [0, 40], // health points (2 = one heart)
  heal: [0, 20],
  potionTicks: [1, 1200], // up to 60 s
  amplifier: [0, 4], // level I..V
  strength: [0, 3], // knockback / pull / push horizontal velocity (blocks per tick)
  vertical: [0, 1.5],
  teleportRange: [1, 16],
  projectileSpeed: [0.2, 3],
  projectileLifetime: [20, 200],
  particleCount: [1, 64],
  particleSpread: [0, 4],
  particleSpeed: [0, 1],
  volume: [0, 2],
  pitch: [0.5, 2],
  giveCount: [1, 64],
  chargeCost: [1, 5],
  markTicks: [20, 1200],
  marksPerOwner: [1, 32],
  queryMarkedRadius: [1, 32],
  queryNearbyRadius: [1, 12],
  queryMax: [1, 16],
  delayTicks: [1, 100],
  chance: [0, 1],
  healthFraction: [0, 1],
  timeOfDay: [0, 23999],
  titleFadeTicks: [0, 40],
  titleStayTicks: [10, 200],
  passiveAmplifier: [0, 2],
  lootChance: [0, 1],
  statDamage: [1, 40], // shown attack damage (player base 1 + modifier)
  statAttackSpeed: [0.25, 4], // attacks per second
  durability: [1, 10000],
  // weapons (2026-10-12): hitscan / beam / area_blast (components/weapons.ts; see WEAPON_LIMITS for the runtime caps)
  hitscanRange: [1, 64],
  pellets: [1, 12],
  spreadDegrees: [0, 15],
  beamRange: [1, 32],
  beamDurationTicks: [10, 100],
  beamIntervalTicks: [2, 20],
  blastRadius: [1, 8],
  playerScale: [0, 1],
  blastMax: [1, 16],
  // techniques (2026-10-12, BF catalogue #2): vein_break (components/veins.ts; see VEIN_LIMITS for the runtime caps)
  veinBlocks: [1, 48], // extra blocks per break (each costs one action of the 64-action budget)
  veinPerTick: [1, 16],
  veinRadius: [1, 12], // blocks from the first broken block
} as const satisfies Record<string, readonly [number, number]>;
export type CapName = keyof typeof CAPS;

/**
 * CRASH-SAFE bounds per cap (D-62). The zod schema, parameter edits and the generated DesignConfig refuse / clamp only
 * outside these; CAPS are the recommended ranges (warnings). Kept exactly: real game ceilings and probabilities.
 */
export const HARD_CAPS = hardCaps(CAPS, {
  chance: [0, 1], healthFraction: [0, 1], lootChance: [0, 1], // probabilities / fractions
  timeOfDay: [0, 23999], // the game's day length
  pitch: [0.5, 2], // the client plays pitch 0.5-2 only
  amplifier: [0, 255], passiveAmplifier: [0, 255], // potion amplifier is a byte
  giveCount: [1, 99], // max stack size component
  strength: [0, 4], vertical: [0, 4], // the Effects component caps velocity at 4 blocks/tick (players get kicked above)
  durability: [1, 2147483647], // item max damage is an int > 0
});

/** Per-activation budget defaults (the static worst case is compared with them; the runtime Budget component enforces them, configurable in config.yml general.budget.*). */
export const BUDGET = { actions: 64, entities: 32, tasks: 8, particles: 512, projectiles: 3 } as const;
/** Plugin-wide runtime caps (component constants). */
export const RUNTIME_CAPS = { liveTasks: 128, marksTotal: 2048, textChars: 120, titleChars: 40, subtitleChars: 60 } as const;
/**
 * Weapon components (designer-weapons, 2026-10-12): every ray costs one ACTION of the activation budget, every tracer /
 * beam / blast particle comes from its particle budget and every target hit costs one ENTITY, so the BUDGET above bounds
 * them (64 rays, 512 particles, 32 hits per activation) whatever config.yml says. Plus fixed per-call caps (Weapons.java
 * constants): tracer points per pellet, beam points per pulse, beam pulses, live beams (one per player, at most 16
 * plugin-wide), blast particles. A weapon on a click trigger needs cooldownTicks >= minClickCooldown: vanilla repeats a
 * held right-click every 4 ticks, so that is the fastest real fire rate; without it a modified client could fire every tick.
 * Full-auto beyond that 4-tick repeat is NOT possible server-side (the client sends no "button held" state): it needs the
 * client-mod lane (docs/cyrus/onboarding/skills/MINECRAFT-FINDINGS.md section 3).
 */
export const WEAPON_LIMITS = { tracerPoints: 24, beamPoints: 16, beamPulses: 50, liveBeams: 16, blastParticles: 8, raySize: 0.2, minClickCooldown: 4 } as const;
