export type ParamSink = { params: Param[]; base: string; item: string; ability?: string; abilityName?: string };
/**
 * cap: an item CAPS name (its HARD_CAPS apply), a CapRange carrying `.hard` (boss / gameplay helpers), or a plain
 * [min, max] that is also the hard bound (text lengths, HUD font geometry: real limits).
 */
export function addParam(s: ParamSink, rel: string, kind: ParamKind, cap: CapName | readonly [number, number] | CapRange, value: number | string, label: string, role: string): Param {
  const [min, max] = Array.isArray(cap) ? (cap as readonly [number, number]) : CAPS[cap as CapName];
  const hard = kind === "text" || kind === "sound" ? [min, max] : Array.isArray(cap) ? ((cap as CapRange).hard ?? [min, max]) : HARD_CAPS[cap as CapName];
  const p: Param = { path: s.base + rel, field: fieldOf(rel), kind, min, max, hardMin: hard[0], hardMax: hard[1], value, label: s.abilityName ? `${s.abilityName}: ${label}` : label, item: s.item, ...(s.ability ? { ability: s.ability } : {}), role };
  s.params.push(p);
  return p;
}

