/**
 * D-62: a parameter outside its recommended range is a WARNING (code outside_recommended / far_outside_recommended),
 * never an error; the message carries the likely consequence. Used by every designer compile and the studios.
 */
export function paramRangeWarnings(params: readonly Param[]): DzIssue[] {
  const out: DzIssue[] = [];
  for (const p of params) {
    if (p.kind === "text" || p.kind === "sound" || typeof p.value !== "number") continue;
    const c = classify(p.value, { recommendedMin: p.min, recommendedMax: p.max, hardMin: p.hardMin, hardMax: p.hardMax }, { label: p.label });
    if (c.tier === "warn" || c.tier === "danger") out.push({ path: p.path, code: c.tier === "danger" ? "far_outside_recommended" : "outside_recommended", message: `${c.message}; it is applied as set${c.consequence ? ` (${c.consequence})` : ""}` });
  }
  return out;
}

