  it("Weapons.java is added only when a design uses a weapon; other mods are untouched", () => {
    const r = compile(ALL());
    const w = r.files.find((f) => f.path.endsWith("/designer/Weapons.java"));
    assert.ok(w); assert.equal(w!.role, "component");
    const v = r.files.find((f) => f.path.endsWith("/designer/Veins.java"));
    assert.ok(v && v.role === "component" && !v.content.includes("__PKG__"));
    const trig = r.files.find((f) => f.path.endsWith("/designer/Trigger.java"))!.content;
    assert.match(trig, /ITEM_CONSUME, CHARGE_RELEASE, BREAK_BLOCK\n/);
    const plain = compileDesigns([JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/void_reaper.json"), "utf8"))], { version: "1.21.11", namespace: "nx_r7design", pluginName: "VoidArsenal" });
    assert.ok(plain.ok);
    assert.ok(!plain.files.some((f) => f.path.endsWith("Veins.java")));
    assert.ok(plain.files.find((f) => f.path.endsWith("/designer/Trigger.java"))!.content.endsWith(TRIGGER_JAVA.replace(/__PKG__/g, plain.pkg).slice(-60)));
    assert.doesNotMatch(plain.files.find((f) => f.path.endsWith("/designer/Trigger.java"))!.content, /BREAK_BLOCK/);

