// Cyrus limits INVENTORY (owner rule 2026-10-12, D-62 "warn, don't block"): every place a limit on a user's choice is
// enforced, classified HARD-KEEP (with a ./policy.ts reason) or SOFTEN, and what it is now. "soften-next" rows are soft
// by policy but still enforced as before in this branch (named honestly so nobody believes they are done). Docs:
// docs/cyrus/03-studios.md "Limits and warnings". Pure data.
import type { HardKeepReason } from "./policy";

export type LimitVerdict = "softened" | "hard-keep" | "soften-next";
export type LimitRow = {
  area: "config" | "designer" | "generated-java" | "perf" | "planner" | "datapack" | "worldgen" | "sound" | "texture" | "model" | "versions" | "service";
  where: string;
  limit: string;
  was: string;
  /** What it is after this branch (softened rows). */
  now?: string;
  verdict: LimitVerdict;
  keep?: HardKeepReason;
  reason: string;
};

const S = (area: LimitRow["area"], where: string, limit: string, was: string, now: string, reason: string): LimitRow => ({ area, where, limit, was, now, verdict: "softened", reason });
const K = (area: LimitRow["area"], where: string, limit: string, was: string, keep: HardKeepReason, reason: string): LimitRow => ({ area, where, limit, was, verdict: "hard-keep", keep, reason });
const N = (area: LimitRow["area"], where: string, limit: string, was: string, reason: string): LimitRow => ({ area, where, limit, was, verdict: "soften-next", reason });

export const LIMIT_INVENTORY: readonly LimitRow[] = [
  // ------------------------------------------------------------------ Config Studio
  S("config", "lib/cyrus/config/values.ts checkValue (Config Studio, ChunkMirror 'Mirror radius 20 chunks is outside the allowed 1-8')", "ConfigSpec min/max", "refused (strict) / clamped (loader)", "recommended range: warn tier (amber, applies), danger past warnMax or 4x max (one confirm); refused only past hardMin/hardMax", "a 
  S("config", "lib/cyrus/config/spec.ts validateConfigSpec", "default / preset outside min/max", "error", "warning (default_outside_recommended / preset_outside_recommended); error only past the crash-safe bounds", "an AI-declared range is advice, not a boundary"),
  S("config", "lib/cyrus/config/spec.ts cellError + values.ts", "list item / table cell min/max", "refused / clamped", "warning; crash-safe bounds only", "same rule for cells"),
  S("config", "components/cyrus/studios/ConfigStudio.tsx", "slider + typed field + red 'outside the allowed' error", "Save disabled on an out-of-range value", "slider over the recommended range, any typed value; amber / red banner with the consequence line; danger needs one checkbox confirm", "warn, don't block"),
  S("config", "lib/cyrus/config/edit.ts planConfigEdit (the 'just type it' box)", "out-of-range value", "sent to the model", "applied, the summary says it is outside the recommended range", "no reason to spend tokens on a number"),
  K("config", "lib/cyrus/config/spec.ts softRangeOf", "derived crash-safe bounds", "-", "crash", "int settings stay inside Java int; a setting whose recommended range is not negative (counts, sizes, radii, durations) never goes below 0"),
  K("config", "lib/cyrus/config/templates.ts", "chance 0-1, armor 30, knockback resistance 0-1, scale 0.0625-16, weather chance 100%", "hard min/max", "api-ceiling", "the game's own attribute / probability limits"),
  K("config", "lib/cyrus/config/spec.ts CONFIG_LIMITS + key / id / file regexes", "400 params, 32 groups, text 1024, key format, file path", "zod", "service-capacity", "untrusted JSON size and path / injection safety"),
  // ------------------------------------------------------------------ generated Java (loaders)
  S("generated-java", "lib/cyrus/config/exporters.ts javaSettingsClass (CyrusSettings)", "num()/range() clamp to min/max", "clamped on load ('clamped k 20 -> 8')", "applied as saved; one warning per key and value; clamp only to crash-safe bounds", "generated plugins must honour saved values"),
