export function inventoryByVerdict(rows: readonly LimitRow[] = LIMIT_INVENTORY): Record<LimitVerdict, LimitRow[]> {
  const out: Record<LimitVerdict, LimitRow[]> = { softened: [], "hard-keep": [], "soften-next": [] };
  for (const r of rows) out[r.verdict].push(r);
  return out;
}
