// Cyrus PROMPT COACH: one coach template per archetype of the Minecraft coverage matrix
// (lib/cyrus/adapters/minecraft-coverage.json, 85 archetypes). A template says how to RECOGNISE the kind of mod a prompt
// asks for (`match`, plain word rules, no model) and which details that kind of mod needs to be built right the first
// time (`dims`, the gap ids of ./analyze.ts) plus the numbers to ask for with sensible defaults (`fields`).
// test/cyrus-coach.test.ts fails when an archetype in the coverage matrix has no template here (or the other way).
// Pure + client-safe (no JSON import here: the 136 KB matrix stays server side, see ./catalogue.ts).

export const GAP_IDS = [
  "what", "trigger", "numbers", "limits", "dimensions", "scope", "persistence", "config",
  "commands", "performance", "edgeCases", "antiAbuse", "modes", "feedback", "version",
] as const;
export type GapId = (typeof GAP_IDS)[number];

/** A number the coach asks for, prefilled with a sensible default the user can change. */
export type CoachField = { key: string; label: string; def: string; unit?: string };
export type CoachTemplate = {
  id: string;
  /** Word rules that recognise the archetype; more hits = better match. */
  match: RegExp[];
  /** The details this kind of mod needs (added to the base set of every request). */
  dims: GapId[];
  /** The numbers to ask for (the "numbers" / "limits" questions). */
  fields?: CoachField[];
  /** Trigger choices for the "when" question (first = default). */
  triggers?: string[];
};

const f = (key: string, label: string, def: string, unit?: string): CoachField => ({ key, label, def, ...(unit ? { unit } : {}) });
const T = (id: string, match: RegExp[], dims: GapId[], fields?: CoachField[], triggers?: string[]): CoachTemplate => ({ id, match, dims, ...(fields ? { fields } : {}), ...(triggers ? { triggers } : {}) });

