export const TEMPLATE_BY_ID: Record<string, CoachTemplate> = Object.fromEntries(COACH_TEMPLATES.map((t) => [t.id, t]));

/** The best-matching archetype for a request (null = none clearly matches; the generic questions apply). */
export function matchArchetype(text: string): { id: string; hits: number } | null {
  const t = text ?? "";
  let best: { id: string; hits: number } | null = null;
  for (const tpl of COACH_TEMPLATES) {
    let hits = 0;
    for (const re of tpl.match) {
      const g = new RegExp(re.source, re.flags.includes("g") ? re.flags : `${re.flags}g`);
      hits += (t.match(g) ?? []).length;
    }
    const strong = STRONG[tpl.id];
    if (strong) hits += 3 * (t.match(new RegExp(strong.source, strong.flags.includes("g") ? strong.flags : `${strong.flags}g`)) ?? []).length;
    if (hits > 0 && (!best || hits > best.hits)) best = { id: tpl.id, hits };
  }
  return best;
}
