export const COACH_FLAG = "CYRUS_PROMPT_COACH";
export const coachOn = (env: Record<string, string | undefined> = process.env) => env[COACH_FLAG] === "1";
// Cyrus PROMPT COACH: the archetype facts the coach shows BEFORE spend (label, how well Cyrus covers it, its limits and
// per-version notes), read from the Minecraft coverage matrix. SERVER side only in practice (the matrix is 136 KB): the
// plan route runs the analysis and sends the client just the lines it needs. Pure (no I/O beyond the static import).
import COVERAGE from "../adapters/minecraft-coverage.json";

export type ArchetypeFacts = {
  id: string;
  label: string;
  category: string;
  status: "covered" | "partial" | "gap" | "impossible" | string;
  lanes: string[];
  limits: string[];
  /** Per-version notes for the chosen version: only the ones that are not plainly "available". */
  versionLines: string[];
};

type RawArchetype = {
  id: string; label: string; category: string; lanes: string[]; limits?: string[];
  coverage?: { status?: string };
  versionNotes?: Record<string, { lane: string; availability: string; reason: string; substitute?: string | null; minVersion?: string | null }[]>;
};

const ARCHETYPES = (COVERAGE as unknown as { archetypes: RawArchetype[] }).archetypes;
export const COVERAGE_ARCHETYPE_IDS: readonly string[] = ARCHETYPES.map((a) => a.id);

export function archetypeFacts(id: string | null | undefined, version: string): ArchetypeFacts | null {
  const a = id ? ARCHETYPES.find((x) => x.id === id) : undefined;
  if (!a) return null;
  const notes = a.versionNotes?.[version] ?? [];
  const versionLines = notes
    .filter((n) => n.availability !== "available")
    .map((n) => `On ${version}: ${n.reason}${n.substitute ? `; Cyrus builds ${n.substitute} instead` : ""}${n.minVersion ? ` (${n.minVersion} or newer has it)` : ""}.`);
  return { id: a.id, label: a.label, category: a.category, status: a.coverage?.status ?? "covered", lanes: a.lanes, limits: a.limits ?? [], versionLines };
}
